import Sns from "./Sns";

function Main(){
	return(
		<div className="main">
			<div className="text_box">
				<strong>01</strong>
				<span>Gowoonsesang Cosmetics</span>
				<h3>건강한 피부로 <br/> 누구나 고운 세상</h3>
				<p>우리는 피부과학으로 고운세상을 만들고 있습니다.</p>
			</div>
			<div className="pc"><img src="/images/main_pc.jpg" alt="main_pc"/></div>
			<div className="mo"><img src="/images/main_mo.jpg" alt="main_mo"/></div>
			<div className="inb">
				<Sns/>
				<a href=""><img src="/images/go-btn.png" alt="go-btn"/></a>
			</div>
		</div>
	)
}

export default Main;
